function icon(name){return '<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+(paths[name]||paths.box)+'"/></svg>';}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
const num=v=>v!=null&&Number.isFinite(Number(v))?new Intl.NumberFormat('zh-CN').format(Number(v)):'—';
function date(v,full=false){if(!v)return '—';const d=new Date(typeof v==='number'?v*1000:v);return Number.isNaN(d.getTime())?'—':d.toLocaleString('zh-CN',full?{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}:{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});}
function since(v){if(!v)return '尚未同步';const d=Date.now()/1000-(typeof v==='number'?v:new Date(v).getTime()/1000);if(d<60)return '刚刚';if(d<3600)return Math.floor(d/60)+' 分钟前';if(d<86400)return Math.floor(d/3600)+' 小时前';return date(v);}
function list(v){return Array.isArray(v)?v:v?.items||v?.data||[];}
function errorText(e){if(e instanceof Error)return e.message;if(typeof e==='string')return e;if(Array.isArray(e))return e.map(x=>x.msg||JSON.stringify(x)).join('；');return e?.message||JSON.stringify(e||'操作失败');}
function setTheme(t){state.theme=t;document.documentElement.dataset.theme=t;localStorage.setItem('dreamina_admin_theme',t);}
function themeButton(){return '<button class="icon-btn" data-action="theme" aria-label="切换明暗主题" title="切换明暗主题">'+icon(state.theme==='dark'?'sun':'moon')+'</button>';}
function brand(){return '<a class="brand" href="#/overview"><span class="brand-mark"><svg viewBox="0 0 40 40" aria-hidden="true"><path d="m12 8 15 3 7 13-15 6-10-9 13-6-10-7Z" fill="white"/><path d="m19 30 3-15 12 9Z" fill="#99f6e4"/></svg></span><span class="brand-name">Dreamina<span>Hub</span></span></a>';}
function button(text,action,kind='',ico=''){return '<button class="btn '+kind+'" data-action="'+action+'">'+(ico?icon(ico):'')+esc(text)+'</button>';}
function iconButton(ico,action,label,id='',kind=''){return '<button class="icon-btn '+kind+'" data-action="'+action+'" '+(id?'data-id="'+esc(id)+'"':'')+' title="'+esc(label)+'" aria-label="'+esc(label)+'">'+icon(ico)+'</button>';}
function badge(label,color='',dot=false){return '<span class="badge '+color+'">'+(dot?'<i class="dot '+(color==='blue'?'':color)+'"></i>':'')+esc(label)+'</span>';}
const statusMap={queued:['排队中','amber'],claimed:['已领取','blue'],submitted:['生成中','blue'],in_progress:['生成中','blue'],processing:['生成中','blue'],running:['生成中','blue'],completed:['已完成','green'],succeeded:['已完成','green'],failed:['失败','red'],uncertain:['待核对','amber'],cancelled:['已取消',''],online:['在线','green'],ready:['就绪','green'],healthy:['正常','green'],authenticated:['已登录','green'],offline:['离线',''],unverified:['未验证','amber'],disabled:['已停用',''],error:['异常','red'],expired:['登录过期','red']};
Object.assign(statusMap,{login_pending:['正在登录','blue'],login_required:['需要登录','amber'],verification_required:['需要验证','amber']});
function statusBadge(v){const m=statusMap[v]||[v||'未验证',''];return badge(m[0],m[1],true);}
function accountStatusBadge(a){const change=proxyChangeState(a);if(change==='checking')return badge(proxyRetryAt(a)>Date.now()/1000?'出口核验待重试':'正在核验出口','amber',true);if(change==='restarting')return badge('出口已核验，节点恢复中','blue',true);if(change==='pending')return badge('出口切换待处理','amber',true);if(!a.enabled)return badge('已停用');if(['login_pending','login_required','verification_required','expired','error'].includes(a.status))return statusBadge(a.status);if(a.scheduling_paused===true)return badge(a.scheduling_pause_reason==='below_credit_threshold'?'积分暂停':a.scheduling_pause_reason==='upstream_risk_cooldown'?'风控冷却':String(a.scheduling_pause_reason||'').startsWith('proxy')?'代理暂停':'调度暂停','amber',true);if(a.min_credit_balance>0&&finiteCount(a.balance)==null)return badge('待确认余额','amber',true);const browserState=managedBrowserState(a.managed_worker);if(browserState==='browser_parked'){const canWake=a.online===true&&a.ready===true;return badge(canWake?'休眠 · 可唤醒':'休眠 · 待复验',canWake?'blue':'amber',true);}if(browserState==='browser_waking')return badge('正在唤醒复验','blue',true);return a.online?badge(a.ready?'就绪':'在线',a.ready?'green':'blue',true):statusBadge(a.status||'offline');}
function finiteCount(value){return typeof value==='number'&&Number.isFinite(value)&&value>=0?value:null;}
function accountCreditSummary(account){
  const minimum=finiteCount(account.min_credit_balance),held=finiteCount(account.reserved_credits),available=finiteCount(account.available_credits);
  let html='<strong>'+(finiteCount(account.balance)==null?'<span class="muted">未确认</span>':num(account.balance))+'</strong>';
  if(held!=null)html+='<div class="entity-meta" title="本地保留额用于避免并发重复占用积分，不代表上游已扣费">本地保留 '+num(held)+' · 可分配 '+(available==null?'未确认':num(available))+'</div>';
  if(minimum>0)html+='<div class="entity-meta account-credit-threshold">余额低于 '+num(minimum)+' 暂停</div>';
  if(account.scheduling_paused===true)html+='<div class="account-scheduling-note">'+esc(account.scheduling_pause_reason==='below_credit_threshold'?'余额低于阈值；刷新余额达标后恢复新任务':account.scheduling_pause_reason==='upstream_risk_cooldown'?'账号风控冷却，等待到期或人工核对后解除':account.scheduling_pause_reason||'当前暂停接收新任务')+'</div>';
  return html;
}
function accountConcurrencySummary(account){
  const worker=account.managed_worker||{},effective=finiteCount(worker.effective_concurrency),active=finiteCount(worker.active_slots),attention=finiteCount(worker.attention_slots),limit=finiteCount(worker.server_slot_limit);
  const configured=finiteCount(account.max_concurrent),target=finiteCount(worker.target_concurrency)??(configured==null?null:limit==null?configured:Math.min(configured,limit)),stopped=['stopped','not_managed'].includes(worker.state);
  const inflight=finiteCount(account.max_inflight),available=finiteCount(account.current_inflight_capacity);
  let html='<span>在途任务 '+num(account.active_tasks||0)+' / 上限 '+(inflight==null?'未上报':num(inflight))+'</span><div class="entity-meta">标签页配置 '+num(account.max_concurrent)+'</div>';
  if(available!=null)html+='<div class="entity-meta">当前生效在途上限 '+num(available)+'</div>';
  if(account.detached_generation_supported===false)html+='<div class="account-scheduling-note">旧节点仍按标签页限制任务容量</div>';
  if(stopped)html+='<div class="entity-meta">运行标签页 0 / 0</div><div class="entity-meta">浏览器节点未运行，启动后按当前配置建立槽位</div>';
  else if(effective!=null)html+='<div class="entity-meta">运行标签页 '+(active==null?'未确认':num(active))+' / '+num(effective)+'</div>';
  else html+='<div class="entity-meta">运行槽位未上报</div>';
  if(limit!=null)html+='<div class="entity-meta">服务器单账号上限 '+num(limit)+'</div>';
  if(!stopped&&worker.configuration_pending===true){
    const shrinking=effective!=null&&target!=null&&target<effective,expanding=effective!=null&&target!=null&&target>effective;
    html+='<div class="account-scheduling-note">'+(shrinking?'标签页缩减待生效：运行 '+num(effective)+'，目标 '+num(target)+'。已有任务完成或核对后，关闭并清理多余槽位':expanding?'标签页扩容待生效：运行 '+num(effective)+'，目标 '+num(target)+'。等待节点确认，已有任务继续执行':'配置正在同步，等待节点确认；已有任务继续执行')+'</div>';
  }
  else if(limit!=null&&account.max_concurrent>limit)html+='<div class="account-scheduling-note">运行槽位受服务器上限约束</div>';
  else if(!stopped&&worker.configuration_pending==null&&effective!=null&&effective!==account.max_concurrent)html+='<div class="account-scheduling-note">配置与运行槽位不同，空闲后生效；实际槽数受服务器上限约束</div>';
  if(attention>0)html+='<div class="account-scheduling-note">'+num(attention)+' 个槽位需要核对</div>';
  return html+workerSupervisionSummary(worker)+'<div class="entity-meta">初始优先级 '+num(account.priority)+'</div>';
}
function managedBrowserState(worker={}){return worker?.worker_state??worker?.state;}
function workerSupervisionSummary(worker={}){
  if(worker.restart_circuit_open===true)return '<div class="account-scheduling-note">'+badge('自动重启已熔断','amber')+'<small>检查节点原因后，手动启动可恢复尝试。</small></div>';
  if(worker.desired_running===false)return '<div class="entity-meta">已手动停止，不自动启动</div>';
  if(managedBrowserState(worker)==='browser_parked')return '<div class="entity-meta">浏览器空闲休眠；领取任务后先唤醒并复验页面</div>';
  if(managedBrowserState(worker)==='browser_waking')return '<div class="entity-meta">正在唤醒浏览器并复验页面，尚未开始生成</div>';
  const next=finiteCount(worker.next_restart_at),failures=finiteCount(worker.restart_failures);
  return (next>0?'<div class="account-scheduling-note">计划重启 '+date(next,true)+'</div>':'')+(failures>0?'<div class="entity-meta">连续恢复失败 '+num(failures)+' 次</div>':'');
}
function toast(message,error=false){const n=document.createElement('div');n.className='toast'+(error?' error':'');n.innerHTML=icon(error?'alert':'checkCircle')+'<span>'+esc(message)+'</span>';document.querySelector('#toast-region').append(n);setTimeout(()=>n.remove(),5000);}
async function api(path,options={}){const headers={'Accept':'application/json',...options.headers};if(options.body!==undefined&&!(options.body instanceof FormData)){headers['Content-Type']='application/json';options.body=JSON.stringify(options.body);}if(options.method&&options.method!=='GET'&&state.csrf)headers['X-CSRF-Token']=state.csrf;const response=await fetch(ROOT+path,{...options,headers,credentials:'same-origin'});let data=null;try{data=await response.json();}catch{}if(!response.ok){const e=new Error(errorText(data?.detail||data?.error||data||('HTTP '+response.status)));e.status=response.status;e.code=data?.error?.code||data?.code||(typeof data?.detail==='object'?data.detail.code:undefined);e.details=data?.error||data?.detail||null;if(response.status===401&&path!=='/login'&&path!=='/me'){state.user=null;closeModal();renderLogin();}throw e;}return data;}
function pageTitle(){return ({overview:'运行概览',accounts:'账号管理',keys:'API 密钥',tasks:'任务记录',workers:'浏览器节点',proxies:'代理 IP',models:'模型能力',docs:'API 文档',settings:'系统设置'})[state.page]||'运行概览';}
function navLink(id,label,ico,mark=''){return '<a href="#/'+id+'" class="'+(state.page===id?'active':'')+'" '+(state.page===id?'aria-current="page"':'')+'>'+icon(ico)+'<span>'+label+'</span>'+(mark?'<span class="nav-badge">'+mark+'</span>':'')+'</a>';}
function shell(){return '<div class="shell"><aside class="sidebar">'+brand()+'<div class="nav-group-label">工作空间</div><nav class="nav" aria-label="工作空间">'+navLink('overview','运行概览','grid')+navLink('tasks','任务记录','layers')+navLink('models','模型能力','image')+'</nav><div class="nav-group-label" style="margin-top:20px">资源管理</div><nav class="nav" aria-label="资源管理">'+navLink('accounts','账号管理','users')+navLink('proxies','代理 IP','link')+navLink('keys','API 密钥','key')+navLink('workers','浏览器节点','server')+'</nav><div class="nav-group-label" style="margin-top:20px">开发与配置</div><nav class="nav" aria-label="开发与配置">'+navLink('docs','API 文档','book','OPENAI')+navLink('settings','系统设置','settings')+'</nav><div class="sidebar-bottom"><div id="worker-mini" class="worker-mini"><div class="worker-mini-title"><span>浏览器执行网络</span><i class="dot"></i></div><small>节点状态将在连接后同步</small></div><div class="sidebar-footer"><span>Dreamina Hub</span><span>v0.13.2</span></div></div></aside><div class="content-wrap"><header class="topbar"><div class="breadcrumb">'+iconButton('menu','menu','展开导航','','mobile-menu')+'<span class="home-label">管理控制台</span>'+icon('chevron')+'<strong>'+esc(pageTitle())+'</strong></div><div class="topbar-actions"><span class="connection"><i class="dot green"></i>管理服务已连接</span><a class="icon-btn" href="#/docs" title="API 文档" aria-label="API 文档">'+icon('book')+'</a>'+themeButton()+'<button class="user-button" data-action="user" title="账号与退出"><span class="avatar">'+esc((state.user?.username||'A').slice(0,1).toUpperCase())+'</span><span>'+esc(state.user?.username||'管理员')+'</span>'+icon('down')+'</button></div></header><main id="main"></main></div></div>';}
function renderLogin(message=''){state.csrf='';app.innerHTML='<div class="login-page"><section class="login-visual">'+brand()+'<div class="login-main"><div class="login-eyebrow"><span class="dot green"></span> YOUR CREATIVE INFRASTRUCTURE</div><h1>每一个创意，<br>都有可靠的<em>执行路径。</em></h1><p>在一个控制台里，连接账号、分配任务，<br>通过统一 API 管理图片与视频生成。</p><div class="login-diagram"><div class="diagram-node">'+icon('code')+'</div><div class="diagram-line"></div><div class="diagram-node">'+icon('layers')+'</div><div class="diagram-line"></div><div class="diagram-node">'+icon('video')+'</div></div></div><div class="login-visual-footer"><span>ONE CONSOLE. CONNECTED ACCOUNTS.</span><span>SELF-HOSTED</span></div></section><section class="login-right"><div class="login-theme">'+themeButton()+'</div><form id="login-form" class="login-form"><div class="login-brand-mobile">'+brand()+'</div><h2>登录管理控制台</h2><p>使用你的管理员账号继续</p><div class="form-error" id="login-error">'+esc(message)+'</div><div class="field"><label for="username">用户名</label><input class="input" id="username" name="username" autocomplete="username" placeholder="输入管理员用户名" required autofocus></div><div class="field"><label for="password">密码</label><input class="input" id="password" name="password" type="password" autocomplete="current-password" placeholder="输入管理员密码" required></div><button class="btn primary" type="submit">登录控制台 '+icon('arrow')+'</button><div class="login-footnote">'+icon('shield')+'<span>管理员登录与客户端 API 密钥相互独立。<br>初始登录信息由服务部署时配置。</span></div></form></section></div>';document.querySelector('#login-form').addEventListener('submit',login);}
async function login(e){e.preventDefault();const form=e.currentTarget,b=form.querySelector('button[type=submit]');b.disabled=true;b.innerHTML='<span class="spinner"></span>正在验证';document.querySelector('#login-error').textContent='';try{const data=await api('/login',{method:'POST',body:{username:form.username.value.trim(),password:form.password.value}});state.user=data.user;state.csrf=data.csrf_token||'';await loadInitial();await navigate();}catch(error){document.querySelector('#login-error').textContent=errorText(error);}finally{if(b.isConnected){b.disabled=false;b.innerHTML='登录控制台 '+icon('arrow');}}}
async function loadInitial(){const r=await Promise.allSettled([api('/settings'),api('/models')]);if(r[0].status==='fulfilled')state.settings=r[0].value;if(r[1].status==='fulfilled')state.models=list(r[1].value);}
function pageHead(title,sub,actions=''){return '<div class="page-head"><div><h1>'+esc(title)+'</h1><p>'+esc(sub)+'</p></div><div class="page-head-actions">'+actions+'</div></div>';}
function dateTag(){return '<span class="date-tag">'+icon('calendar')+new Date().toLocaleDateString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit'})+'</span>';}
function empty(title,text,ico='box',action=''){return '<div class="table-empty"><div class="empty-icon">'+icon(ico)+'</div><h3>'+esc(title)+'</h3><p>'+esc(text)+'</p>'+action+'</div>';}
function notice(text,kind='info'){return '<div class="notice '+(kind==='warning'?'warning':'')+'">'+icon(kind==='warning'?'alert':'info')+'<div>'+text+'</div></div>';}
function panelHead(title,sub='',action=''){return '<div class="panel-head"><div><h2>'+esc(title)+'</h2>'+(sub?'<small>'+esc(sub)+'</small>':'')+'</div>'+action+'</div>';}
function footer(){return '<footer class="page-footer"><span>Dreamina Hub · 自部署管理平台</span><span>图片与视频，统一调用</span></footer>';}
async function navigate(){if(!state.user)return renderLogin();const page=(location.hash.slice(2)||'overview').split('?')[0];if(!['overview','accounts','keys','tasks','workers','proxies','models','docs','settings'].includes(page)){location.hash='/overview';return;}if(page!==state.page){state.search='';state.filter='';state.kind='';}state.page=page;const seq=++state.seq;app.innerHTML=shell();const main=document.querySelector('#main');main.innerHTML=pageHead(pageTitle(),'正在同步最新数据…')+'<div class="metrics">'+Array(4).fill('<div class="skeleton metric"></div>').join('')+'<div class="skeleton long"></div>';try{const endpoints={overview:'/dashboard',accounts:'/accounts',keys:'/keys',tasks:'/tasks?limit=100',workers:'/workers',proxies:'/proxies',models:'/models',settings:'/settings'};if(endpoints[page]){const data=await api(endpoints[page]);if(seq!==state.seq)return;state.cache[page]=data;if(page==='models')state.models=list(data);if(page==='proxies')state.proxySupported=true;if(page==='settings')state.settings=data;}if(page==='workers'){const [accounts,monitoring]=await Promise.all([api('/accounts'),api('/monitoring')]);if(seq!==state.seq||!state.user)return;state.cache.accounts=accounts;state.cache.monitoring=monitoring;}if(page==='accounts')await loadProxyChoices();if(page==='keys'){const data=await api('/accounts');if(seq!==state.seq)return;state.cache.accounts=data;}if(page==='overview'||page==='tasks'){const reliability=await loadReliability();if(seq!==state.seq||!state.user)return;state.cache.reliability=reliability;}if(seq!==state.seq)return;renderPage();updateWorkerMini();}catch(e){if(seq!==state.seq||!state.user)return;main.innerHTML=pageHead(pageTitle(),'暂时未能同步数据')+'<div class="error-panel"><h2>连接遇到问题</h2><p>'+esc(errorText(e))+'</p>'+button('重新加载','refresh','primary','refresh')+'</div>';}}
function renderPage(){const main=document.querySelector('#main');if(!main)return;document.title=pageTitle()+' · '+(state.settings.platform_name||'Dreamina Hub');const renderer={overview:renderOverview,accounts:renderAccounts,keys:renderKeys,tasks:renderTasks,workers:renderWorkers,proxies:renderProxies,models:renderModels,docs:renderDocs,settings:renderSettings}[state.page];main.innerHTML=renderer()+footer();bindPage();}
function updateWorkerMini(){const el=document.querySelector('#worker-mini');if(!el)return;let online=state.cache.overview?.summary?.accounts_online,suffix='个账号在线';if(state.cache.workers){online=list(state.cache.workers).filter(w=>w.online).length;suffix='个执行槽位在线';}if(online!==undefined)el.innerHTML='<div class="worker-mini-title"><span>浏览器执行网络</span><i class="dot '+(online?'green':'')+'"></i></div><small>'+num(online)+' '+suffix+'</small>';}
function metric(label,value,note,ico,color=''){return '<div class="metric-card"><div class="metric-top"><span>'+label+'</span><div class="metric-symbol '+color+'">'+icon(ico)+'</div></div><div class="metric-value">'+value+'</div><div class="metric-note">'+note+'</div></div>';}
async function loadReliability(){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),5000);try{const value=await api('/reliability',{signal:controller.signal});return value?.scope==='all_recorded_video_tasks'&&value.overall&&Number.isFinite(value.overall.accepted)?value:null;}catch{return null;}finally{clearTimeout(timer);}}
function reliabilityPercent(value,lower=false){if(typeof value!=='number'||!Number.isFinite(value)||value<0||value>100)return '—';return (lower?Math.floor(value*100)/100:value).toFixed(2)+'%';}
function renderReliability(value=state.cache.reliability){
  if(!value?.overall||!Number.isFinite(value.overall.accepted))return '<section class="panel panel-section reliability-panel">'+panelHead('视频生成可靠性','目标 99% · 优化目标，不是成功率保证')+'<div class="panel-body muted">可靠性统计暂不可用，任务列表仍可正常查看。</div></section>';
  const s=value.overall,count=v=>Number.isFinite(v)&&v>=0?v:0,models=Array.isArray(value.by_model)?value.by_model:[],failures=Array.isArray(value.failure_categories)?value.failure_categories:[];
  const target=s.sample_supports_target?'当前样本下界达到目标，非长期保证':'观测样本尚未支持 99% 目标';
  const stat=(label,number,note)=>'<div class="reliability-stat"><span>'+label+'</span><strong>'+number+'</strong><small>'+note+'</small></div>';
  return '<section class="panel panel-section reliability-panel">'+panelHead('视频生成可靠性','全部已落库视频任务；权限失败、取消和待核对均保留',badge('目标 99%','blue'))+'<div class="panel-body"><div class="reliability-grid">'+
    stat('自动完成率',reliabilityPercent(s.automatic_closed_success_rate_percent),(Number.isFinite(s.automatic_completed)?num(count(s.automatic_completed)):'—')+' / '+num(count(s.terminal))+' · 分母含全部已结束任务')+
    stat('全部已接收交付占比',reliabilityPercent(s.accepted_completion_rate_percent),num(count(s.completed))+' / '+num(count(s.accepted))+' · 含手工核对交付')+
    stat('未完成 / 待核对',num(count(s.active))+' / '+num(count(s.uncertain)),'未知状态 '+num(count(s.unknown))+' · 均不算成功')+
    stat('经手工核对完成',num(count(s.manual_reconciled_completed)),num(count(s.manual_reconciled))+' 项曾需手工核对')+
    '</div><div class="reliability-evidence"><strong>'+target+'</strong><span>已结束样本 '+num(count(s.terminal))+' 项 · 自动完成率的 95% 双侧 Wilson 下界 '+reliabilityPercent(s.automatic_wilson_95_lower_percent,true)+'</span><small>已结束任务总交付成功率 '+reliabilityPercent(s.closed_success_rate_percent)+'（'+num(count(s.completed))+' / '+num(count(s.terminal))+'，含手工核对恢复）。自动查询恢复仍计入自动完成，手工核对完成单列。</small><small>至少 '+num(count(value.evidence?.minimum_all_success_terminal_samples_for_target)||381)+' 次全部自动完成，才可能让该下界达到 99%。历史任务包含不同模型和参数，统计不构成长期保证。</small></div>'+
    '<details class="reliability-details"><summary>按模型与失败原因查看</summary><div class="table-wrap"><table><thead><tr><th>模型</th><th>已接收</th><th>总交付 / 失败 / 取消</th><th>待核对</th><th>已结束：自动 / 总交付</th></tr></thead><tbody>'+models.map(m=>'<tr><td class="mono">'+esc(m.model)+'</td><td>'+num(count(m.accepted))+'</td><td>'+num(count(m.completed))+' / '+num(count(m.failed))+' / '+num(count(m.cancelled))+'</td><td>'+num(count(m.uncertain))+'</td><td>'+reliabilityPercent(m.automatic_closed_success_rate_percent)+' / '+reliabilityPercent(m.closed_success_rate_percent)+'</td></tr>').join('')+'</tbody></table></div><div class="reliability-failures">'+failures.filter(f=>count(f.count)>0).map(f=>badge(String(f.label||'')+' · '+num(count(f.count)),'amber')).join('')+'</div><small class="muted">API 鉴权或参数校验阶段未创建任务的拒绝不在本统计中；统计覆盖全部历史视频记录，不限于最近 100 条。</small></details></div></section>';
}
function usageChart(items){const data=Array.isArray(items)?items:[],max=Math.ceil(Math.max(1,...data.map(x=>Number(x.requests)||0))/3)*3,plotW=610,left=28,top=15,bottom=173;let lines='';for(let i=0;i<4;i++){const y=top+(bottom-top)*i/3;lines+='<line x1="'+left+'" x2="650" y1="'+y+'" y2="'+y+'" class="chart-grid"/><text x="0" y="'+(y+4)+'">'+Math.ceil(max*(3-i)/3)+'</text>';}const barW=Math.min(30,plotW/Math.max(data.length,1)*.52);let bars='';data.forEach((x,i)=>{const xx=left+(i+.5)*plotW/data.length,total=Math.max(0,Number(x.requests)||0),height=total/max*(bottom-top);bars+='<rect x="'+(xx-barW/2)+'" y="'+(bottom-height)+'" width="'+barW+'" height="'+height+'" rx="3" fill="var(--accent)" opacity=".82"><title>'+esc(x.date)+'：'+total+' 次请求</title></rect>';if(data.length<=8||i%2===0)bars+='<text x="'+xx+'" y="197" text-anchor="middle">'+esc(String(x.date||'').slice(5))+'</text>';});return '<div class="chart"><svg viewBox="0 0 660 208" preserveAspectRatio="none" role="img" aria-label="每日真实请求数量">'+lines+bars+'</svg>'+(!data.some(x=>x.requests)?'<div class="chart-empty-label">还没有请求记录，开始调用后将在这里展示</div>':'')+'</div>';}
function distributionRow(label,value,kind){return '<div class="status-row"><span><i class="legend-dot '+kind+'"></i>'+label+'</span><strong>'+num(value)+'</strong></div>';}
function miniRow(label,value){return '<div class="mini-list-row"><span class="label">'+esc(label)+'</span><span class="value">'+value+'</span></div>';}
function renderOverview(){const d=state.cache.overview||{},s=d.summary||{},completed=Number(s.tasks_completed)||0,failed=Number(s.tasks_failed)||0,active=Number(s.tasks_active)||0,total=Number(s.tasks_total)||0,success=s.success_rate==null?'—':Number(s.success_rate).toFixed(1)+'%';return pageHead('运行概览','查看生成任务、账号资源与 API 使用情况',dateTag()+button('刷新','refresh','','refresh'))+'<section class="metrics">'+metric('累计任务',num(s.tasks_total),'<strong>'+num(s.requests_today)+'</strong> 今日请求','layers')+metric('在线账号',num(s.accounts_online),'<span>共 '+num(s.accounts_total)+' 个账号 · '+num(s.accounts_enabled)+' 个启用</span>','users','blue')+metric('综合历史成功率',success,'图片+视频：完成 ÷（完成+失败）','activity','violet')+metric('API 密钥',num(s.keys_total),'独立权限与请求额度','key','amber')+'</section>'+renderReliability()+'<section class="grid two"><div class="panel">'+panelHead('请求趋势','每日 API 请求记录','<div class="chart-legend"><span><i class="legend-dot"></i>请求数量</span></div>')+'<div class="panel-body">'+usageChart(d.daily_usage)+'</div></div><div class="panel">'+panelHead('任务状态','当前任务的处理分布')+'<div class="panel-body distribution"><div class="distribution-total">'+num(total)+'<small>累计任务</small></div><div class="segment-track">'+(total?'<span class="segment" style="width:'+completed/total*100+'%"></span><span class="segment active" style="width:'+active/total*100+'%"></span><span class="segment failed" style="width:'+failed/total*100+'%"></span>':'')+'</div>'+distributionRow('已完成',completed,'')+distributionRow('进行中 / 排队',active,'active')+distributionRow('失败',failed,'failed')+'</div></div></section><section class="panel panel-section">'+panelHead('最近任务','所有账号的最新生成记录','<a href="#/tasks" class="link">查看全部 '+icon('arrow')+'</a>')+tasksTable(d.recent_tasks||[],true)+'</section><section class="grid equal panel-section"><div class="panel">'+panelHead('调用入口','使用平台签发的 API Key 统一调用')+'<div class="panel-body"><div class="mini-list">'+miniRow('Base URL','<span class="mono">'+esc(location.origin+'/v1')+'</span>')+miniRow('鉴权方式','<span class="mono">Authorization: Bearer sk-dr-…</span>')+miniRow('接口类型','图片 · 异步视频')+'</div><a href="#/docs" class="btn small" style="margin-top:10px">查看调用示例 '+icon('arrow')+'</a></div></div><div class="panel">'+panelHead('能力与验证','每项模型能力独立标记；未实测组合明确保留状态')+'<div class="panel-body"><div class="feature-list"><div class="feature-item">'+icon('checkCircle')+'<div><p>Chrome 原生视频生成链路</p><small>Mini · 4 秒 · 720p · 16:9 已完成端到端验证</small></div></div><div class="feature-item">'+icon('image')+'<div><p>Seedream 5.0 Lite 图片生成</p><small>2K · 1 张，原生生成与协议已验证，SDK 返回 JPEG base64</small></div></div><div class="feature-item">'+icon('shield')+'<div><p>独立账号与密钥访问范围</p><small>任务绑定原账号，不确定提交不会自动重发</small></div></div><div class="feature-item">'+icon('info')+'<div><p>模型能力以当前配置为准</p><small>四模型已接入参数与执行器；新会话及参考素材结果以实测记录为准</small></div></div></div></div></div></section>';}
function searchBox(placeholder){return '<div class="search-input">'+icon('search')+'<input class="input" id="search" aria-label="'+esc(placeholder)+'" placeholder="'+esc(placeholder)+'" value="'+esc(state.search)+'"></div>';}
function filtered(items,kind){let values=items;const q=state.search.toLowerCase();if(q)values=values.filter(x=>(x.name+' '+x.id+' '+(x.prompt||'')+' '+(x.model||'')+' '+(x.prefix||'')+' '+(x.host||'')+' '+(x.exit_ip||'')+' '+(x.country||'')).toLowerCase().includes(q));if(state.filter){if(kind==='accounts')values=values.filter(x=>state.filter==='enabled'?x.enabled:state.filter==='disabled'?!x.enabled:state.filter==='paused'?x.enabled&&x.scheduling_paused===true:state.filter==='online'?x.online:true);else if(kind==='keys')values=values.filter(x=>state.filter==='enabled'?x.enabled:!x.enabled);else values=values.filter(x=>x.status===state.filter);}if(state.kind)values=values.filter(x=>x.kind===state.kind);return values;}
function filterSelect(options,value,id='status-filter',label='状态筛选'){return '<select class="filter-select" id="'+id+'" aria-label="'+label+'">'+options.map(([v,t])=>'<option value="'+v+'" '+(value===v?'selected':'')+'>'+t+'</option>').join('')+'</select>';}
function renderAccounts(){const items=list(state.cache.accounts);return pageHead('账号管理','管理独立登录环境、账号凭据与均衡调度',button('刷新','refresh','','refresh')+button('添加账号','account-add','primary','plus'))+'<section class="panel"><div class="filters">'+searchBox('搜索账号名称或 ID')+filterSelect([['','全部状态'],['enabled','已启用'],['disabled','已停用'],['paused','积分暂停'],['online','在线']],state.filter)+'<span class="filter-count">共 '+num(items.length)+' 个账号</span></div><div id="account-table">'+accountsTable(filtered(items,'accounts'))+'</div></section><div class="section-gap">'+notice('可用账号优先分配给当前图片＋视频任务数最少的账号，同负载时轮流派发，顺序跨重启保留。离线、登录失效、冷却或满额账号跳过；不同模型权限、容量和任务耗时可能使实际并发暂时不同。 可设置余额暂停阈值，低于阈值不派发新任务。单账号以独立任务标签页并行执行，配置上限与运行槽位分别展示。每次生成前结合网页报价、最新余额及本地保留积分检查；积分不足只在确认尚未提交时切换账号。报价或余额未知时不会按0积分猜测，也不会重复提交已生成任务。')+'</div>';}
function accountBlockingTasks(account){const current=finiteCount(account.blocking_tasks);return current==null?Math.max(0,Number(account.active_tasks)||0):current;}
function accountSessionBlocked(account){return !!proxyChangeState(account)||accountBlockingTasks(account)>0||(finiteCount(account.blocking_tasks)==null&&account.blocked_by_uncertain===true)||account.status==='login_pending';}
function accountLoginButton(account){const blocked=accountSessionBlocked(account),changing=!!proxyChangeState(account);let html=iconButton('link','account-login',changing?'出口切换或核验尚未完成，请等待自动恢复':blocked?'仍有执行或待核对任务，暂不能重新登录':account.secret_configured?'重新登录':'登录账号',account.id);return blocked?html.replace('<button ','<button disabled '):html;}
function managedWorkerButton(account){if(!account.browser_profile_saved)return '';const running=['running','starting','running_unverified','browser_parked','browser_waking'].includes(account.managed_worker?.state),changing=!!proxyChangeState(account),busy=changing||running&&accountSessionBlocked(account);let html=iconButton(running?'pause':'server',running?'account-worker-stop':'account-worker-start',changing?'出口切换或核验尚未完成，节点由后台恢复':busy?'仍有执行或待核对任务，暂不能停止节点':running?'停止托管节点':'启动托管节点',account.id);return busy?html.replace('<button ','<button disabled '):html;}
function accountCooldowns(account){
  const until=finiteCount(account.risk_cooldown_until),riskActive=until!=null&&until>Date.now()/1000;
  const blocks=Array.isArray(account.model_blocks)?account.model_blocks.filter(b=>typeof b?.model==='string'&&b.model&&typeof b.blocked_until==='number'&&Number.isFinite(b.blocked_until)&&b.reason!=='upstream_risk_cooldown'):[];
  if(!blocks.length&&!riskActive)return '';
  const risk=riskActive?'<div class="account-model-cooldown risk-cooldown"><div><strong>账号风控冷却（全部模型）</strong><small>至 '+date(until,true)+'</small></div><button class="btn small" data-action="account-risk-unblock" data-id="'+esc(account.id)+'">核对并解除</button></div>':'';
  return '<div class="account-model-cooldowns">'+risk+blocks.map(block=>'<div class="account-model-cooldown"><div><strong>'+esc(block.model)+'</strong><small>本地冷却至 '+date(block.blocked_until)+'</small></div><button type="button" class="btn small" data-action="account-model-unblock" data-id="'+esc(account.id)+'" data-model="'+esc(block.model)+'" title="仅解除本地调度冷却，不会更改网站套餐或权限">解除冷却</button></div>').join('')+'<small>解除仅恢复本地调度，网站权限仍需核对。</small></div>';
}
async function clearModelCooldown(id,model,el){if(!id||!model)return;el.disabled=true;try{await api('/accounts/'+encodeURIComponent(id)+'/model-blocks/'+encodeURIComponent(model),{method:'DELETE'});toast('本地冷却已解除；网站权限仍以实际账号状态为准。');await navigate();}catch(error){toast(errorText(error),true);if(el.isConnected)el.disabled=false;}}
function accountsTable(rows){rows=rows.filter(a=>a.deleted_at==null&&a.status!=='deleted');if(!rows.length)return empty('没有匹配的账号','创建账号后直接在后台登录，登录状态会独立保存。','users',button('添加账号','account-add','primary small','plus'));return '<div class="table-wrap"><table><thead><tr><th>账号</th><th>区域 / 状态</th><th>凭据 / 出口</th><th>积分</th><th>并发 / 初始顺序</th><th>最近检查</th><th style="text-align:right">操作</th></tr></thead><tbody>'+rows.map(a=>'<tr><td><div class="table-entity"><span class="avatar square">'+esc((a.name||a.id).slice(0,1).toUpperCase())+'</span><div><div class="entity-name">'+esc(a.name||a.id)+'</div><div class="entity-meta mono">'+esc(a.id)+'</div></div></div></td><td><div class="pill-list"><span class="region-flag">'+esc(a.region)+'</span>'+accountStatusBadge(a)+'</div>'+accountCooldowns(a)+'</td><td>'+badge(a.secret_configured?'已配置':'待配置',a.secret_configured?'green':'amber')+accountEgressSummary(a)+'</td><td>'+accountCreditSummary(a)+'</td><td>'+accountConcurrencySummary(a)+'</td><td>'+since(a.last_checked_at)+'</td><td><div class="row-actions">'+accountLoginButton(a)+iconButton('refresh','account-check','检查登录与积分',a.id)+iconButton('edit','account-edit','编辑账号',a.id)+managedWorkerButton(a)+iconButton(a.enabled?'pause':'play','account-toggle',a.enabled?'停用账号':'启用账号',a.id,a.enabled?'danger':'')+accountDeleteButton(a)+'</div></td></tr>').join('')+'</tbody></table></div><div class="table-footer"><span>显示 '+rows.length+' 个账号</span><span>优先最少并发，同负载按最近派发顺序轮流分配</span></div>';}
function renderKeys(){const items=list(state.cache.keys);return pageHead('API 密钥','为不同调用方设置独立的模型权限、账户范围和额度',button('刷新','refresh','','refresh')+button('创建密钥','key-add','primary','plus'))+'<section class="panel"><div class="filters">'+searchBox('搜索密钥名称或前缀')+filterSelect([['','全部状态'],['enabled','已启用'],['disabled','已停用']],state.filter)+'<span class="filter-count">共 '+num(items.length)+' 个密钥</span></div><div id="key-table">'+keysTable(filtered(items,'keys'))+'</div></section><div class="section-gap">'+notice('密钥只在创建时完整显示一次。后续仅显示前缀；管理员登录凭据、客户端 API 密钥和浏览器配对凭据相互独立。')+'</div>';}
