  const maintenance=value.maintenance&&typeof value.maintenance==='object'?value.maintenance:{};
  const freed=finiteCount(maintenance.bytes_reclaimed),free=finiteCount(maintenance.disk_free_bytes);
  const maintenanceHtml='<p class="privacy-note">维护：'+esc(maintenance.state==='completed'?'检查完成':maintenance.state==='error'?'检查失败':maintenance.state==='not_run'?'尚未执行':'等待数据')+(freed!=null?' · 本轮释放 '+(freed/1024/1024).toFixed(1)+' MiB':'')+(free!=null?' · 可用磁盘 '+(free/1024/1024/1024).toFixed(1)+' GiB':'')+'。登录状态与待核对任务保留；中央成品/输入清理默认关闭，启用后仅清理过期且无活动引用的已知终态文件。</p>';
