  const pacingHtml=pacing.length?'<details class="monitor-pacing"><summary>提交节流状态</summary><ul>'+pacing.map(p=>'<li><span class="mono">'+esc(typeof p.scope==='string'?p.scope:'未知范围')+'</span><span>'+(p.awaiting_receipt===true?'等待原提交回执':finiteCount(p.wait_seconds)>0?'至少等待 '+num(p.wait_seconds)+' 秒':'可重新检查提交许可')+'</span><small>'+(finiteCount(p.next_allowed_at)>0?'下次检查 '+date(p.next_allowed_at,true):'')+'</small>'+(p.job_id?'<button class="btn small" data-action="gate-release" data-scope="'+esc(p.scope)+'" '+(gateReleaseAllowed(p)?'':'disabled')+' title="'+esc(gateReleaseAllowed(p)?'只释放许可，不释放任务与积分':p.release_block_reason||'尚无安全释放证明')+'">核对后释放许可</button>':'')+'</li>').join('')+'</ul></details>':'';
  const lag=finiteCount(metrics.event_loop_lag_ms)??finiteCount(metrics.loop_lag_ms),memory=finiteCount(metrics.process_memory_bytes)??finiteCount(metrics.memory_bytes),disk=finiteCount(metrics.disk_used_percent);
  const browserMemory=finiteCount(metrics.browser_memory_bytes),browserCount=Number.isInteger(metrics.browser_processes)&&metrics.browser_processes>=0?metrics.browser_processes:null,hasBrowserMetrics=Object.hasOwn(metrics,'browser_memory_bytes')||Object.hasOwn(metrics,'browser_processes');
  const browserHtml=hasBrowserMetrics?'<span>托管浏览器 RSS 合计 '+(browserMemory!=null?(browserMemory/1024/1024).toFixed(1)+' MiB':'未知')+'</span><span>浏览器进程 '+(browserCount!=null?num(browserCount):'未知')+'</span><small class="monitor-memory-note">浏览器 RSS 是已确认归属的浏览器进程合计，共享内存页可能重复计数，属于上界估计；与 API 进程内存分开统计，不代表整台服务器的实际物理内存占用。</small>':'';
  const performanceHtml='<div class="monitor-performance">'+(lag!=null?'<span>事件循环延迟 '+num(lag)+' ms</span>':'')+(memory!=null?'<span>API 进程内存 '+(memory/1024/1024).toFixed(1)+' MiB</span>':'')+(disk!=null?'<span>磁盘使用 '+num(disk)+'%</span>':'')+browserHtml+'</div>';
  const proxyRows=Array.isArray(value.proxies)?value.proxies.filter(p=>p&&typeof p==='object').slice(0,100):[];
