  const accountMetrics=Array.isArray(value.account_metrics)?value.account_metrics.filter(a=>a&&typeof a==='object').slice(0,100):[];
  const accountMetricsHtml=accountMetrics.length?'<details class="monitor-pacing"><summary>账号成功率与耗时</summary><div class="table-wrap"><table><thead><tr><th>账号</th><th>成功 / 已结束</th><th>成功率</th><th>准备 P50 / P95</th><th>生成 P50 / P95</th><th>-6 / 2052</th></tr></thead><tbody>'+accountMetrics.map(a=>'<tr><td class="mono">'+esc(a.account_id)+'</td><td>'+num(a.completed)+' / '+num(a.terminal)+'</td><td>'+(finiteCount(a.success_rate_percent)!=null?num(a.success_rate_percent)+'%':'—')+'</td><td>'+num(a.preparation_p50_seconds)+' / '+num(a.preparation_p95_seconds)+'秒</td><td>'+num(a.generation_p50_seconds)+' / '+num(a.generation_p95_seconds)+'秒</td><td>'+num(a.risk_rejections)+' / '+num(a.audio_rejections)+'</td></tr>').join('')+'</tbody></table></div></details>':'';
  return '<section class="panel monitor-panel section-gap">'+panelHead('运行监控与告警','最近检查 '+date(value.observed_at,true))+'<div class="panel-body"><div class="monitor-metrics">'+items+'</div>'+performanceHtml+listHtml+pacingHtml+proxyHtml+accountMetricsHtml+maintenanceHtml+'</div></section>';
