function accountDeleteReason(account){
  if(proxyChangeState(account))return '出口切换或核验尚未完成，完成后才能删除账号';
  if(account.status==='login_pending')return '正在登录，结束登录后才能删除账号';
  if(account.blocked_by_uncertain||account.status==='uncertain')return '存在待核对任务，核对完成后才能删除账号';
  if(Number(account.active_tasks)>0)return '存在未结束任务，任务完成后才能删除账号';
  return '';
}
function accountDeleteButton(account){
  const reason=accountDeleteReason(account),html=iconButton('trash','account-delete',reason||'删除账号',account.id,'danger');
  return reason?html.replace('<button ','<button disabled '):html;
}
function keyAccountChoices(selected=[]){
  const accounts=list(state.cache.accounts).filter(a=>a.deleted_at==null&&a.status!=='deleted');
  const known=new Set(accounts.map(a=>a.id));
  return accounts.concat(selected.filter(id=>!known.has(id)).map(id=>({id,name:'已删除或不可用账号 · '+id,unavailable:true})));
}
function confirmDelete(kind,id){
  if(!['account','key'].includes(kind))return;
  const collection=kind==='account'?'accounts':'keys';
  const item=list(state.cache[collection]).find(x=>x.id===id&&x.deleted_at==null&&x.status!=='deleted');
  if(!item)return;
  const blocked=kind==='account'?accountDeleteReason(item):'';
  if(blocked){toast(blocked,true);return;}
  state.dialog={kind:'delete',resource:kind,id};
  const description=kind==='account'
    ? '删除时会停止此账号对应的浏览器节点并清理节点登记，完成后账号从列表移除并退出调度，不能通过“启用”恢复。仍有任务、待核对结果或节点未能停止时不会确认删除。历史任务及结果保留，查询所需的加密凭据和浏览器资料也会保留；如需再次使用，请重新添加账号并登录。'
    : '删除后密钥立即失效并从列表移除，不能恢复使用。已提交的任务仍会继续处理，历史任务和结果保留，可在管理后台查看；客户端将不能再用此密钥查询或下载。';
  openModal('删除'+(kind==='account'?'账号':'密钥'),'确认删除「'+(item.name||item.id)+'」？',
    '<p class="sub" style="font-size:13px;line-height:1.9">'+description+'</p>',
    button('取消','modal-close')+button('确认删除','confirm-delete','danger','trash'));
}
async function doDelete(el){
  const d=state.dialog;
  if(d?.kind!=='delete'||!['account','key'].includes(d.resource)||el.disabled)return;
  el.disabled=true;
  const collection=d.resource==='account'?'accounts':'keys';
  let result;
  try{result=await api('/'+collection+'/'+encodeURIComponent(d.id),{method:'DELETE'});if(result?.deleted!==true)throw new Error('服务端尚未确认删除，请刷新页面或升级服务后重试。');}
  catch(error){toast(errorText(error),true);if(el.isConnected)el.disabled=false;return;}
  const cached=state.cache[collection],remaining=list(cached).filter(item=>item.id!==d.id);
  state.cache[collection]=Array.isArray(cached)?remaining:{...(cached||{}),items:remaining,data:remaining};
  const cleanupPending=d.resource==='account'&&result.nodes_cleanup_pending===true;
  if(cleanupPending)await refreshCachedWorkers();
  else if(d.resource==='account'&&state.cache.workers){const cachedWorkers=state.cache.workers,remainingWorkers=list(cachedWorkers).filter(worker=>worker.account_id!==d.id);state.cache.workers=Array.isArray(cachedWorkers)?remainingWorkers:{...cachedWorkers,items:remainingWorkers,data:remainingWorkers};updateWorkerMini();}
  if(state.dialog===d)closeModal();toast(cleanupPending?'账号已删除，节点清理待完成':d.resource==='account'?'账号及对应节点已删除，历史任务保留':'密钥已删除并立即失效');
  if(state.page===collection)refreshTable();
  try{await navigate();}catch(error){toast('删除已完成，列表刷新失败：'+errorText(error),true);}
}

function confirmToggle(kind,id){const item=list(state.cache[kind==='account'?'accounts':'keys']).find(x=>x.id===id);if(!item)return;const disabling=item.enabled;state.dialog={kind:'toggle',resource:kind,id,enabled:!disabling};openModal((disabling?'停用':'启用')+(kind==='account'?'账号':'密钥'),'确认要'+(disabling?'停用':'启用')+'「'+item.name+'」吗？','<p class="sub" style="font-size:13px;line-height:1.9">'+(disabling?(kind==='account'?'停用后不再为此账号分配新任务。已经提交的任务不会因此取消。':'停用后该密钥不能创建新的请求。已有任务和记录仍保留。'):'启用后恢复参与服务，仍会检查登录、模型权限和额度。')+'</p>',button('取消','modal-close')+button(disabling?'确认停用':'确认启用','confirm-toggle',disabling?'danger':'primary'));}
