function findTask(id){return [...list(state.cache.tasks),...(state.cache.overview?.recent_tasks||[])].find(t=>t.id===id);}
const creditEventLabels={credit_preflight:'生成前积分检查',credit_preflight_passed:'积分检查通过',credit_insufficient:'余额不足，尚未生成',account_reassigned:'生成前切换账号',credit_failover_exhausted:'无可切换账号',credit_quote_unavailable:'无法确认当前报价',credit_check_unavailable:'无法确认当前余额'};
const retryEventLabels={submission_retry_scheduled:'计划新会话重试',submission_retry_started:'开始新会话重试',submission_retry_exhausted:'提交重试次数已用完',submission_retry_budget_rejected:'重试超出费用限制',submission_retry_cancelled:'取消新会话重试',submission_retry_completed:'重试任务完成',submission_retry_stopped:'停止新会话重试',upstream_diagnostics:'上游错误诊断'};
