async function taskDialog(id){try{const t=await api('/tasks/'+encodeURIComponent(id));const details=[['任务 ID',t.id],['模型',t.model],['所属账号',t.account_id],['调用密钥',t.key_id],['上游任务 ID',t.submit_id||'尚未确认'],['独立会话 ID',t.conversation_id||'等待新会话确认'],['创建时间',date(t.created_at,true)],['完成时间',date(t.completed_at,true)],['计费状态',t.billing_status||'上游未提供'],['用量',t.usage?JSON.stringify(t.usage):'上游未提供']];const sections=[['请求详细记录',t.request_detail||{parameters:t.request}],['上游响应摘要',t.result],['错误详情',t.error]];const timeline=(t.events||[]).map(e=>'<li><strong>'+esc(taskEventLabel(e.stage))+'</strong><span class="task-event-code mono">'+esc(e.stage)+'</span><time>'+date(e.created_at,true)+'</time><pre>'+esc(JSON.stringify(e.detail,null,2))+'</pre></li>').join('');openModal('任务详情','请求、会话、进度和上游结果，凭据与媒体内容不写入日志','<div>'+statusBadge(t.status)+taskProgress(t)+'</div>'+taskIssueSummary(t,true)+taskRetrySummary(t,true)+taskCreditSummary(t)+taskReconcilePanel(t)+'<div class="detail-grid">'+details.map(([k,v])=>'<div class="detail-item"><small>'+esc(k)+'</small><span>'+esc(v)+'</span></div>').join('')+'</div>'+sections.map(([title,data],i)=>'<details class="section-gap" '+(i===0?'open':'')+'><summary>'+esc(title)+'</summary><pre class="json-block">'+esc(JSON.stringify(data??{},null,2))+'</pre></details>').join('')+'<section class="section-gap"><h3>事件时间线</h3><ol class="task-timeline">'+(timeline||'<li>此历史任务没有记录事件。</li>')+'</ol></section>',button('关闭','modal-close'),true);const reconcileForm=modal.querySelector('#task-reconcile-form');if(reconcileForm)reconcileForm.addEventListener('submit',event=>submitTaskReconcile(event,t));}catch(error){toast(errorText(error),true);}}

function proxyManagementAvailable(){return state.proxySupported===true||typeof state.settings.account_proxy_required==='boolean'||typeof state.settings.proxy_required==='boolean';}
function proxyRequired(){return state.settings.account_proxy_required??state.settings.proxy_required??proxyManagementAvailable();}
async function loadProxyChoices(){try{state.cache.proxies=await api('/proxies');state.proxySupported=true;state.proxyLoadError='';}catch(error){state.proxyLoadError='代理列表暂不可用';if(error.status===404)state.proxySupported=false;}}
function proxyErrorText(error){const labels={proxy_ip_unavailable:'Dreamina可达，当前出口IP暂未取得；新绑定需等待IP探测恢复。',account_proxy_check_retry:'出口核验遇到临时错误，已保留切换状态并安排自动重试。',proxy_restart_pending:'出口已验证，浏览器节点恢复待完成。'};return labels[error?.code]||labels[error?.message]||errorText(error).replace(/\b(https?|socks5h?):\/\/[^\s/@]+@/gi,'$1://[凭据已隐藏]@').replace(/\b(password|authorization|token)\s*[=:]\s*[^\s;,]+/gi,'$1=[已隐藏]');}
function proxyAuthority(proxy){const host=typeof proxy?.host==='string'?proxy.host:'';if(!host||/[\s/@?#]/.test(host))return '地址未提供';return (host.includes(':')&&!host.startsWith('[')?'['+host+']':host)+':'+(Number.isInteger(proxy.port)&&proxy.port>0?proxy.port:'—');}
function proxyBoundCount(proxy){return finiteCount(proxy.bound_accounts_count)??finiteCount(proxy.account_count)??0;}
function proxyStatus(proxy){if(proxy.browser_supported===false)return badge('浏览器不支持','amber');if(proxy.status==='disabled')return badge('已停用');if(proxy.status==='failing')return badge('探测失败','red');if(finiteCount(proxy.expires_at)>0&&proxy.expires_at<=Date.now()/1000)return badge('已过期','red');if(proxy.ip_known===false&&proxy.warning_code==='proxy_ip_unavailable')return badge('网站可达，出口IP待确认','amber');if(!proxy.last_checked_at||!proxy.exit_ip)return badge('待检测','amber');return badge('可用','green',true);}
function proxyExpiry(proxy){if(!proxy.expires_at)return '<span class="muted">无到期时间</span>';const remain=proxy.expires_at-Date.now()/1000,warn=(finiteCount(proxy.expiry_warn_days)??3)*86400;return '<span>'+date(proxy.expires_at,true)+'</span>'+(remain<=0?'<div>'+badge('已到期','red')+'</div>':remain<=warn?'<div>'+badge('即将到期','amber')+'</div>':'');}
function proxyChangeState(account){const value=account.proxy_change?.state??account.proxy_change_state;return ['pending','checking','restarting'].includes(value)?value:account.status==='proxy_changing'?'pending':null;}
function proxyRetryAt(account){return finiteCount(account.proxy_change?.retry_at??account.proxy_retry_at)??0;}
function proxyChangeSummary(account){
  const state=proxyChangeState(account);if(!state)return '';
  const retry=proxyRetryAt(account),count=finiteCount(account.proxy_change?.retry_count??account.proxy_retry_count);
  const message=state==='checking'?'新出口验证尚未完成，暂缓新任务；会自动重试。':state==='restarting'?'出口验证已完成，正在恢复原浏览器节点。':'正在安全切换出口，等待原节点停止并核验新出口。';
  return '<div class="account-scheduling-note">'+message+(state==='checking'&&retry>0?' 下次尝试 '+esc(date(retry,true)):'')+(state==='checking'&&count>0?' · 已安排重试 '+num(count)+' 次':'')+'</div>';
}
function proxyIPPolicyLabel(proxy){return proxy.ip_change_policy==='pause'?'IP变化时暂停新任务':'IP变化时仅告警';}
function accountEgressSummary(account){
  const proxy=account.proxy||list(state.cache.proxies).find(p=>p.id===account.proxy_id);
  const issue=account.proxy_scheduling_error?badge('出口待处理，暂停调度','amber'):'',changed=account.proxy_ip_changed===true?badge(account.proxy_ip_change_policy==='pause'?'出口IP已变化，等待确认':'出口IP已变化（仅告警）','amber'):'';
  if(account.proxy_id)return '<div class="account-egress"><strong>'+esc(proxy?.name||account.proxy_name||account.proxy_id)+'</strong><small>'+esc(proxy?proxyAuthority(proxy):account.proxy_exit_ip_at_bind||'等待代理信息')+'</small><small>'+esc([proxy?.exit_ip||account.proxy_exit_ip_at_bind,proxy?.country,account.browser_timezone].filter(Boolean).join(' · '))+'</small>'+issue+changed+proxyChangeSummary(account)+'</div>';
  if(issue)return '<div class="account-egress">'+issue+proxyChangeSummary(account)+'</div>';
  if(!proxyManagementAvailable())return '';
  return '<div class="account-egress">'+badge(proxyRequired()?'缺少代理，暂停调度':'直连（显式允许）',proxyRequired()?'amber':'')+proxyChangeSummary(account)+'</div>';
}
function proxyOptions(selected='',exclude=''){
  const rows=list(state.cache.proxies).filter(p=>p&&p.id!==exclude&&p.deleted_at==null);
  if(selected&&!rows.some(p=>p.id===selected))rows.push({id:selected,name:'当前绑定（暂不可用）',status:'disabled'});
  return rows.map(p=>'<option value="'+esc(p.id)+'" '+(p.id===selected?'selected':'')+'>'+esc((p.name||p.id)+' · '+(p.country||'地区未知')+' · '+(finiteCount(p.latency_ms)!=null?num(p.latency_ms)+'ms':'未探测')+' · '+proxyBoundCount(p)+'/'+(p.max_accounts??3)+'账号'+(p.browser_supported===false?' · 浏览器不支持':p.status==='disabled'?' · 已停用':p.status==='failing'?' · 失败':''))+'</option>').join('');
}
function accountProxyField(account,edit){
  if(!proxyManagementAvailable())return '<div class="field full"><small>代理管理需要服务端支持；当前保持原出口配置。</small></div>';
  return '<div class="field full account-proxy-select"><label for="f-proxy_id">账号出口代理'+(proxyRequired()?'（必选）':'')+'</label><div class="proxy-select-line"><select id="f-proxy_id" name="proxy_id" '+(!edit&&proxyRequired()?'required':'')+'><option value="">'+(proxyRequired()?'请选择代理':'直连（当前服务显式允许）')+'</option>'+proxyOptions(account.proxy_id||'')+'</select><button type="button" class="btn small" data-action="proxy-test-selected">测试所选代理</button></div><small>'+(edit?'更换仅在账号空闲时进行，先探测，再停止节点、切换和校验登录。':'先选择并检测代理，再打开登录面板；登录与后续任务使用同一出口。')+' 代理失败不会回退直连。</small>'+(state.proxyLoadError?'<small class="form-error">'+esc(state.proxyLoadError)+'</small>':'')+'</div>';
}
function renderProxies(){
  const rows=list(state.cache.proxies).filter(p=>p.deleted_at==null);
  return pageHead('代理 IP','为账号管理固定出口、健康状态与到期时间',button('刷新','refresh','','refresh')+button('测试全部','proxy-test-all','','activity')+button('批量导入','proxy-batch','','plus')+button('添加代理','proxy-add','primary','plus'))+
    notice(proxyRequired()?'当前要求账号绑定代理；未绑定、过期或不可用的代理会暂停相关账号，绝不回退直连。':'当前服务显式允许未绑定账号直连；已绑定代理不可用时仍暂停该账号，不会回退直连。',proxyRequired()?'info':'warning')+
    '<section class="panel section-gap"><div class="filters">'+searchBox('搜索名称、主机、出口 IP 或国家')+filterSelect([['','全部状态'],['active','已启用'],['disabled','已停用'],['failing','故障']],state.filter)+'<span class="filter-count">共 '+rows.length+' 个代理</span></div><div id="proxy-table">'+proxiesTable(filtered(rows,'proxies'))+'</div></section><p class="privacy-note">仅展示代理 ID 和脱敏连接信息。用户名、密码和完整代理串不会回显；带认证的 SOCKS5 若服务端暂不支持，请改用带认证的 HTTP(S) 代理。</p>';
}
function proxiesTable(rows){
  rows=rows.filter(p=>p.deleted_at==null);if(!rows.length)return empty('还没有匹配的代理','添加代理并测试可用性后，即可绑定账号。','link',button('添加代理','proxy-add','primary small','plus'));
  return '<div class="table-wrap"><table class="proxy-table"><thead><tr><th>代理</th><th>连接 / 认证</th><th>出口 / 地区</th><th>状态 / 延迟</th><th>绑定账号</th><th>到期时间</th><th>操作</th></tr></thead><tbody>'+rows.map(p=>'<tr><td><strong>'+esc(p.name||p.id)+'</strong><div class="entity-meta mono">'+esc(p.id)+'</div></td><td><div class="proxy-endpoint mono">'+esc(String(p.protocol||'').toUpperCase())+' '+esc(proxyAuthority(p))+'</div><div class="entity-meta">'+(p.has_username||p.has_password?'认证已配置':'无认证')+'</div></td><td><span class="mono">'+esc(p.exit_ip||'未探测')+'</span><div class="entity-meta">'+esc([p.country,p.region,p.city].filter(Boolean).join(' / ')||'地区未知')+'</div><div class="entity-meta">'+esc(p.timezone||'时区未知')+'</div><div class="entity-meta">'+proxyIPPolicyLabel(p)+'</div></td><td>'+proxyStatus(p)+'<div class="entity-meta">'+(finiteCount(p.latency_ms)!=null?num(p.latency_ms)+' ms':'延迟未知')+' · '+since(p.last_checked_at)+'</div>'+(p.last_error?'<div class="proxy-error">'+esc(proxyErrorText({message:String(p.last_error).slice(0,500)}))+'</div>':'')+'</td><td><button class="btn small" data-action="proxy-accounts" data-id="'+esc(p.id)+'">'+num(proxyBoundCount(p))+' / '+num(p.max_accounts??3)+'</button></td><td>'+proxyExpiry(p)+'</td><td><div class="row-actions">'+iconButton('activity','proxy-test','测试代理',p.id)+iconButton('edit','proxy-edit','编辑代理',p.id)+iconButton(p.status==='disabled'?'play':'pause','proxy-toggle',p.status==='disabled'?'启用代理':'停用代理',p.id)+(proxyBoundCount(p)>0?'<button class="icon-btn" disabled title="仍有账号绑定，不能删除">'+icon('trash')+'</button>':iconButton('trash','proxy-delete','删除代理',p.id,'danger'))+'</div></td></tr>').join('')+'</tbody></table></div>';
}
function proxyDialog(id){
  const p=list(state.cache.proxies).find(x=>x.id===id)||{},edit=!!id;
  state.dialog={kind:'proxy',id};
  const expires=p.expires_at?new Date(p.expires_at*1000-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16):'';
  const body='<form id="proxy-form"><div class="form-error" role="alert"></div><div class="form-grid">'+field('代理名称','proxy_name',p.name||'','text','','required maxlength="120"')+field('最多绑定账号','max_accounts',p.max_accounts??3,'number','默认3；超出上限时需再次确认。','required min="1" max="1000"')+'<div class="field full"><label for="proxy-url">'+(edit?'替换连接信息（可选）':'连接信息')+'</label><input id="proxy-url" name="url" class="input mono" type="password" autocomplete="new-password" spellcheck="false" maxlength="4096" '+(!edit?'required':'')+' placeholder="http://user:pass@host:port"><small>'+(edit?'留空保留原凭据；不会从服务器读取完整代理串。':'支持http、https、socks5、socks5h；特殊字符请使用URL百分号编码。')+'</small></div>'+field('到期时间','expires_at',expires,'datetime-local','留空表示未设置。')+field('提前提醒天数','expiry_warn_days',p.expiry_warn_days??3,'number','默认提前3天提醒；0表示仅在到期时提示。','required min="0" max="365"')+'<div class="field"><label for="f-ip_change_policy">出口IP变化策略</label><select id="f-ip_change_policy" name="ip_change_policy"><option value="warn" '+(p.ip_change_policy!=='pause'?'selected':'')+'>仅告警，保留调度</option><option value="pause" '+(p.ip_change_policy==='pause'?'selected':'')+'>暂停新任务，等待确认</option></select><small>默认仅告警；代理故障、到期或手动停用仍会暂停新任务，不回退直连。</small></div><div class="field"><label for="f-fallback_mode">过期处理</label><select id="f-fallback_mode" name="fallback_mode"><option value="none" '+(p.fallback_mode!=='proxy'?'selected':'')+'>暂停，等待处理</option><option value="proxy" '+(p.fallback_mode==='proxy'?'selected':'')+'>使用备用代理（空闲时）</option></select><small>不提供直连回退。</small></div><div class="field"><label for="f-backup_proxy_id">备用代理</label><select id="f-backup_proxy_id" name="backup_proxy_id"><option value="">无</option>'+proxyOptions(p.backup_proxy_id||'',id)+'</select></div><div class="field full"><label for="proxy-notes">备注</label><textarea id="proxy-notes" name="notes" maxlength="1000">'+esc(p.notes||'')+'</textarea></div></div></form>';
  openModal(edit?'编辑代理':'添加代理',edit?'已绑定代理的连接变更需经过服务端空闲与出口校验':'创建后先探测，再绑定账号',body,button('取消','modal-close')+'<button class="btn primary" type="submit" form="proxy-form">保存代理</button>',true);
  modal.querySelector('#proxy-form')?.addEventListener('submit',e=>saveProxy(e,id));
}
function proxyFormBody(form,edit){
  const f=new FormData(form),url=String(f.get('url')||'').trim(),fallback=String(f.get('fallback_mode')||'none'),backup=String(f.get('backup_proxy_id')||'');
  const value={name:String(f.get('proxy_name')||'').trim(),max_accounts:Number(f.get('max_accounts')),notes:String(f.get('notes')||'').trim(),expiry_warn_days:Number(f.get('expiry_warn_days')),fallback_mode:fallback,backup_proxy_id:backup||null,expires_at:f.get('expires_at')?Math.floor(new Date(f.get('expires_at')).getTime()/1000):null,ip_change_policy:String(f.get('ip_change_policy')||'warn')};
  if(!value.name||value.name.length>120)throw new Error('请填写最多120字的代理名称。');
  if(!Number.isInteger(value.max_accounts)||value.max_accounts<1||value.max_accounts>1000)throw new Error('绑定上限必须为1–1000的整数。');
  if(!Number.isInteger(value.expiry_warn_days)||value.expiry_warn_days<0||value.expiry_warn_days>365)throw new Error('提醒天数必须为0–365的整数。');
  if(!['warn','pause'].includes(value.ip_change_policy))throw new Error('出口IP变化策略必须为仅告警或暂停新任务。');
  if(value.expires_at!==null&&!Number.isFinite(value.expires_at))throw new Error('到期时间无效。');
  if(!['none','proxy'].includes(fallback)||fallback==='proxy'&&!backup)throw new Error('请选择可用的备用代理，或关闭自动改投。');
  if(!edit&&!url)throw new Error('请填写代理连接信息。');
  if(url){if(url.length>4096||! /^(https?|socks5h?):\/\//i.test(url)||/[\r\n]/.test(url))throw new Error('代理串格式无效，请使用protocol://user:pass@host:port。');value.url=url;}
  return value;
}
async function saveProxy(event,id){
  event.preventDefault();const form=event.currentTarget,submit=modal.querySelector('[type=submit]'),error=form.querySelector('.form-error');
  try{const body=proxyFormBody(form,!!id);if(submit)submit.disabled=true;error.textContent='';await api('/proxies'+(id?'/'+encodeURIComponent(id):''),{method:id?'PUT':'POST',body});form.elements?.url&&(form.elements.url.value='');closeModal();await loadProxyChoices();await navigate();toast('代理已保存；可用状态以探测结果为准。');}
  catch(problem){error.textContent=proxyErrorText(problem);if(submit&&submit.isConnected!==false)submit.disabled=false;}
}
function proxyBatchDialog(){
  state.dialog={kind:'proxy-batch'};
  openModal('批量导入代理','每行一条完整代理串；凭据只用于这次请求，不保存在浏览器存储中','<form id="proxy-batch-form"><div class="form-error" role="alert"></div><div class="field"><label for="proxy-lines">代理列表</label><textarea id="proxy-lines" name="lines" autocomplete="off" spellcheck="false" maxlength="200000" rows="8" required placeholder="http://user:pass@host:port&#10;socks5://host:port"></textarea><small>最多200个非空行、200000字符。先校验整批内容，全部通过后统一保存；任一条目保存失败则整批回滚。重复配置由服务端去重，导入后仍需探测通过再绑定账号。</small></div></form>',button('取消','modal-close')+'<button class="btn primary" type="submit" form="proxy-batch-form">导入代理</button>',true);
  modal.querySelector('#proxy-batch-form')?.addEventListener('submit',saveProxyBatch);
}
async function saveProxyBatch(event){
  event.preventDefault();const form=event.currentTarget,error=form.querySelector('.form-error'),submit=modal.querySelector('[type=submit]');
  const lines=String(form.elements?.lines?.value||'').trim();
  if(!lines||lines.length>200000||lines.split(/\r\n|[\r\n]/).filter(x=>x.trim()).length>200){error.textContent='请填写1–200个非空行代理，内容不超过200000字符。';return;}
  if(submit)submit.disabled=true;
  try{const result=await api('/proxies/batch',{method:'POST',body:{lines}});
    if(Array.isArray(result?.errors)&&result.errors.length)throw new Error('服务端未确认整批导入完成，请刷新代理列表核对后重试。');
    if(!Array.isArray(result?.items))throw new Error('服务端未确认导入结果，请刷新代理列表核对后重试。');
    form.elements.lines.value='';closeModal();await loadProxyChoices();await navigate();
    toast('整批代理导入完成，重复配置已去重；请检查探测结果。');
  }catch(problem){error.textContent=proxyErrorText(problem);if(submit&&submit.isConnected!==false)submit.disabled=false;}
}
async function testProxy(id,el){if(!id)return;el.disabled=true;try{await api('/proxies/'+encodeURIComponent(id)+'/test',{method:'POST'});await loadProxyChoices();if(state.page==='proxies')renderPage();toast('代理探测完成，请查看状态和出口信息。');}catch(error){toast(proxyErrorText(error),true);}finally{if(el.isConnected!==false)el.disabled=false;}}
async function testSelectedProxy(el){const value=modal.querySelector('[name=proxy_id]')?.value;if(!value){toast('请先选择代理。',true);return;}await testProxy(value,el);}
async function testAllProxies(el){
  const rows=list(state.cache.proxies).filter(p=>p.deleted_at==null&&p.status!=='disabled');if(!rows.length){toast('没有已启用的代理可测试。');return;}
  el.disabled=true;let failures=0;
  try{for(const p of rows){try{await api('/proxies/'+encodeURIComponent(p.id)+'/test',{method:'POST'});}catch{failures++;}}await loadProxyChoices();if(state.page==='proxies')renderPage();toast('批量探测完成'+(failures?'，'+failures+'项未完成':'')+'。',failures>0);}finally{if(el.isConnected!==false)el.disabled=false;}
}
function confirmProxyToggle(id){const p=list(state.cache.proxies).find(x=>x.id===id);if(!p)return;const status=p.status==='disabled'?'active':'disabled';state.dialog={kind:'proxy-mutation',id,method:'PUT',body:{status}};openModal(status==='disabled'?'停用代理':'启用代理',p.name||id,notice(status==='disabled'?'绑定此代理的账号会暂停新调度，不会退回直连；已提交任务仍需查询原结果。':'启用后仍需健康检查通过；不会更换账号出口。','warning'),button('取消','modal-close')+button('确认','proxy-confirm-mutation',status==='disabled'?'danger':'primary'));
}
function confirmProxyDelete(id){const p=list(state.cache.proxies).find(x=>x.id===id);if(!p)return;if(proxyBoundCount(p)>0){toast('仍有账号绑定此代理，不能删除。',true);return;}state.dialog={kind:'proxy-mutation',id,method:'DELETE'};openModal('删除代理',p.name||id,'<p class="privacy-note">仅删除无账号绑定的代理。已绑定或被备用链引用时，服务端会拒绝删除。</p>',button('取消','modal-close')+button('确认删除','proxy-confirm-mutation','danger'));
}
async function doProxyMutation(el){const d=state.dialog;if(d?.kind!=='proxy-mutation'||el.disabled)return;el.disabled=true;try{await api('/proxies/'+encodeURIComponent(d.id),{method:d.method,...(d.body?{body:d.body}:{})});closeModal();await loadProxyChoices();await navigate();toast('代理已更新。');}catch(error){toast(proxyErrorText(error),true);if(el.isConnected!==false)el.disabled=false;}}
async function proxyAccountsDialog(id){try{const result=await api('/proxies/'+encodeURIComponent(id)+'/accounts');const accounts=list(result);openModal('绑定账号','只显示账号标识与当前调度状态',accounts.length?'<ul class="proxy-bound-accounts">'+accounts.map(a=>'<li><strong>'+esc(a.name||a.id)+'</strong><span class="mono">'+esc(a.id)+'</span>'+accountStatusBadge(a)+'</li>').join('')+'</ul>':'<p class="privacy-note">当前没有账号绑定此代理。</p>',button('关闭','modal-close'));}catch(error){toast(proxyErrorText(error),true);}}
async function bindAccountProxy(accountId,proxyId,flags={}){
  const body={proxy_id:proxyId,confirm_country_change:flags.confirm_country_change===true,confirm_capacity_override:flags.confirm_capacity_override===true};
  try{const result=await api('/accounts/'+encodeURIComponent(accountId)+'/proxy',{method:'POST',body});if(result?.pending===true){closeModal();await navigate();toast(result.state==='restarting'?'出口已核验，浏览器节点恢复待完成':'代理切换已受理，出口核验等待自动重试；尚未确认完成');return false;}return true;}
  catch(error){
    const capacity=error.code==='proxy_capacity_confirmation_required',country=error.code==='proxy_country_confirmation_required';
    if(!capacity&&!country)throw error;
    state.dialog={kind:'proxy-bind-confirm',accountId,proxyId,flags:body,confirmation:capacity?'confirm_capacity_override':'confirm_country_change'};
    openModal(capacity?'确认超出代理绑定上限':'确认更换出口国家','账号基本配置已保存，代理尚未切换',notice(capacity?'此代理绑定数量将超过设置上限。确认后才会继续探测和安全切换。':'新代理所在国家与原出口不同，可能需要重新登录或人工验证。确认后才会继续切换。','warning'),button('暂不切换','modal-close')+button('确认切换','proxy-bind-confirm','primary'));
    return false;
  }
}
async function confirmPendingProxyBinding(el){const d=state.dialog;if(d?.kind!=='proxy-bind-confirm'||el.disabled)return;el.disabled=true;try{const done=await bindAccountProxy(d.accountId,d.proxyId,{...d.flags,[d.confirmation]:true});if(!done)return;closeModal();await loadProxyChoices();await navigate();toast('代理已切换，登录状态及节点按服务端校验结果更新。');}catch(error){toast(proxyErrorText(error),true);if(el.isConnected!==false)el.disabled=false;}}
function confirmCreateWithProxy(body){state.dialog={kind:'proxy-create-account-confirm',create:async()=>api('/accounts',{method:'POST',body:{...body,confirm_capacity_override:true}})};openModal('确认代理绑定上限','账号尚未创建',notice('所选代理将超过绑定账号上限。确认后使用同一账号 ID 创建并绑定，随后打开登录面板。','warning'),button('取消','modal-close')+button('确认创建','proxy-create-account-confirm','primary'));}
async function doConfirmCreateWithProxy(el){const d=state.dialog;if(d?.kind!=='proxy-create-account-confirm'||el.disabled)return;el.disabled=true;try{const result=await d.create();const id=result?.id||result?.account?.id;if(!id)throw new Error('创建响应缺少账号 ID，请刷新列表核对，不要重复创建。');closeModal();await navigate();await openAccountLogin(id);}catch(error){toast(proxyErrorText(error),true);if(el.isConnected!==false)el.disabled=false;}}
function riskCooldownDialog(id){const a=list(state.cache.accounts).find(x=>x.id===id);if(!a)return;state.dialog={kind:'risk-clear',id};openModal('解除账号风控冷却',a.name||id,'<p class="privacy-note">只解除本地调度冷却，不改变网站风控状态，不重发历史失败任务，也不释放未知任务的积分。</p><form id="risk-clear-form"><div class="form-error" role="alert"></div><div class="field"><label for="risk-note">处理说明</label><textarea id="risk-note" name="note" maxlength="500" required placeholder="说明核对情况"></textarea></div><button type="submit" class="btn primary">解除本地冷却</button></form>',button('取消','modal-close'));modal.querySelector('#risk-clear-form')?.addEventListener('submit',event=>submitRiskCooldown(event,id));}
async function submitRiskCooldown(event,id){event.preventDefault();const f=event.currentTarget,b=f.querySelector('[type=submit]'),error=f.querySelector('.form-error'),note=String(f.elements?.note?.value||'').trim();if(!note||note.length>500){error.textContent='请填写1–500字处理说明。';return;}b.disabled=true;try{await api('/accounts/'+encodeURIComponent(id)+'/risk-cooldown',{method:'DELETE',body:{note}});closeModal();await navigate();toast('账号本地风控冷却已解除，历史任务未重发。');}catch(e){error.textContent=errorText(e);if(b.isConnected!==false)b.disabled=false;}}
function gateReleaseAllowed(gate){return gate?.can_release===true;}
function gateReleaseDialog(scope){
  const gate=(state.cache.monitoring?.pacing||[]).find(g=>g.scope===scope);if(!gate||!gateReleaseAllowed(gate)){toast('服务端尚未确认可安全释放，请先核对原任务或节点。',true);return;}
  state.dialog={kind:'gate-release',scope};openModal('释放提交等待许可',scope,'<p class="privacy-note">只释放节流等待，不释放任务并发或积分预留，不取消上游任务，也不重新生成。服务端会再次核对关闭或未激活证明。</p><form id="gate-release-form"><div class="form-error" role="alert"></div><div class="field"><label for="gate-note">核对说明</label><textarea id="gate-note" name="note" required maxlength="500"></textarea></div><button class="btn primary" type="submit">确认释放许可</button></form>',button('取消','modal-close'));modal.querySelector('#gate-release-form')?.addEventListener('submit',event=>submitGateRelease(event,scope));
}
async function submitGateRelease(event,scope){event.preventDefault();const f=event.currentTarget,b=f.querySelector('[type=submit]'),error=f.querySelector('.form-error'),note=String(f.elements?.note?.value||'').trim();if(!note||note.length>500){error.textContent='请填写1–500字核对说明。';return;}b.disabled=true;try{await api('/submission-gates/'+encodeURIComponent(scope)+'/release',{method:'POST',body:{note}});closeModal();await navigate();toast('提交等待许可已释放，任务及积分保护保持。');}catch(e){error.textContent=errorText(e);if(b.isConnected!==false)b.disabled=false;}}

function workerHelp(){openModal('连接无扩展浏览器节点','每个账号使用独立的持久化 Chrome 配置','<ol class="intro-list"><li>配置 browser-worker.json：服务地址、Worker 密钥、账号 ID 和独立 profile_dir。</li><li>运行 <span class="mono">python -m dreamina_api.browser_worker login --config browser-worker.json --account default</span>，在专用浏览器正常登录一次。</li><li>运行 <span class="mono">python -m dreamina_api.browser_worker run --config browser-worker.json --account default</span>，无需安装扩展。</li><li>服务端设置 WORKER_MODE=native 后，旧扩展不再领取任务；后台显示执行器类型和心跳状态。</li></ol>'+notice('已提交任务在重启后不会重新点击。Linux 建议用持久化浏览器与虚拟显示，实际环境须单独验证。详见 NATIVE_WORKER.md。'),button('知道了','modal-close','primary'),true);}

async function checkAccount(id,el){el.disabled=true;el.innerHTML='<span class="spinner" style="width:14px;height:14px"></span>';try{await api('/accounts/'+encodeURIComponent(id)+'/check',{method:'POST'});toast('账号检查完成');await navigate();}catch(e){toast(errorText(e),true);if(el.isConnected){el.disabled=false;el.innerHTML=icon('refresh');}}}
async function saveSettings(e){e.preventDefault();const form=e.currentTarget,b=form.querySelector('[type=submit]');b.disabled=true;try{const data=await api('/settings',{method:'PATCH',body:{platform_name:form.platform_name.value.trim(),default_image_timeout:Number(form.default_image_timeout.value)}});state.settings={...state.settings,...data};toast('系统设置已保存');await navigate();}catch(error){form.querySelector('.form-error').textContent=errorText(error);if(b.isConnected)b.disabled=false;}}
async function copy(value){try{await navigator.clipboard.writeText(value);toast('已复制到剪贴板');}catch{toast('浏览器未允许复制，请手动选择文本复制。',true);}}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;switch(action){case 'theme':setTheme(state.theme==='dark'?'light':'dark');document.querySelectorAll('[data-action=theme]').forEach(b=>b.innerHTML=icon(state.theme==='dark'?'sun':'moon'));break;case 'menu':document.querySelector('.shell')?.classList.toggle('sidebar-open');break;case 'refresh':await navigate();break;case 'modal-close':closeModal();break;case 'account-add':accountDialog();break;case 'account-edit':accountDialog(id);break;case 'account-login':await openAccountLogin(id);break;case 'account-worker-start':await accountWorker(id,'start',el);break;case 'account-worker-stop':await accountWorker(id,'stop',el);break;case 'account-toggle':confirmToggle('account',id);break;case 'account-delete':confirmDelete('account',id);break;case 'account-check':await checkAccount(id,el);break;case 'account-model-unblock':await clearModelCooldown(id,el.dataset.model,el);break;case 'proxy-add':proxyDialog();break;case 'proxy-edit':proxyDialog(id);break;case 'proxy-batch':proxyBatchDialog();break;case 'proxy-test':await testProxy(id,el);break;case 'proxy-test-selected':await testSelectedProxy(el);break;case 'proxy-test-all':await testAllProxies(el);break;case 'proxy-toggle':confirmProxyToggle(id);break;case 'proxy-delete':confirmProxyDelete(id);break;case 'proxy-confirm-mutation':await doProxyMutation(el);break;case 'proxy-accounts':await proxyAccountsDialog(id);break;case 'proxy-bind-confirm':await confirmPendingProxyBinding(el);break;case 'proxy-create-account-confirm':await doConfirmCreateWithProxy(el);break;case 'account-risk-unblock':riskCooldownDialog(id);break;case 'gate-release':gateReleaseDialog(el.dataset.scope);break;case 'key-add':keyDialog();break;case 'key-edit':keyDialog(id);break;case 'key-toggle':confirmToggle('key',id);break;case 'key-delete':confirmDelete('key',id);break;case 'confirm-delete':await doDelete(el);break;case 'confirm-toggle':await doToggle(el);break;case 'task-view':taskDialog(id);break;case 'worker-help':workerHelp();break;case 'copy-key':if(state.dialog?.key)await copy(state.dialog.key);break;case 'copy-code':await copy(state.docsCode);break;case 'docs-tab':state.docsTab=id;renderPage();break;case 'docs-example':state.docsExample=id;renderPage();break;case 'user':openModal('管理员会话','当前登录：'+(state.user?.username||'管理员'),'<div class="notice">'+icon('shield')+'<div>管理会话使用 HttpOnly Cookie。退出仅结束当前管理会话，不会停止浏览器节点或已经提交的任务。</div></div>',button('取消','modal-close')+button('退出登录','logout','danger','logout'));break;case 'logout':try{await api('/logout',{method:'POST'});}finally{state.user=null;state.cache={};closeModal();renderLogin();}break;}});
modal.addEventListener('cancel',()=>{releaseAccountLogin();state.dialog=null;});
modal.addEventListener('close',()=>{if(!modal.open){releaseAccountLogin();modal.innerHTML='';state.dialog=null;}});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
window.addEventListener('hashchange',()=>{if(state.user)navigate();});
setTheme(localStorage.getItem('dreamina_admin_theme')||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'));
(async()=>{try{const session=await api('/me');state.user=session.user;state.csrf=session.csrf_token||'';await loadInitial();await navigate();}catch(e){renderLogin(e.status===401?'':errorText(e));}})();

setInterval(async()=>{if(!state.user||!['overview','tasks','workers'].includes(state.page)||document.querySelector('dialog[open]')||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;try{const paths={overview:'/dashboard',tasks:'/tasks?limit=100',workers:'/workers'};const page=state.page;const data=await api(paths[page]);if(state.page===page){state.cache[page]=data;if(page==='workers'){const [accounts,monitoring]=await Promise.all([api('/accounts'),api('/monitoring')]);if(state.page!==page)return;state.cache.accounts=accounts;state.cache.monitoring=monitoring;}renderPage();updateWorkerMini();}}catch{}},5000);
